import{_ as a,c as i,o as s,a2 as t}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"macOS Permissions Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/screen-recording.md","filePath":"guide/screen-recording.md","lastUpdated":1780466351000}'),r={name:"guide/screen-recording.md"};function o(n,e,l,c,p,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="macos-permissions-guide" tabindex="-1">macOS Permissions Guide <a class="header-anchor" href="#macos-permissions-guide" aria-label="Permalink to &quot;macOS Permissions Guide&quot;">​</a></h1><p>Gomoku may request a small set of macOS permissions for specific features. This page explains what they are and how to manage them.</p><h2 id="local-network-required-for-lan-play" tabindex="-1">Local Network (required for LAN play) <a class="header-anchor" href="#local-network-required-for-lan-play" aria-label="Permalink to &quot;Local Network (required for LAN play)&quot;">​</a></h2><p>When you first host or join a LAN game, macOS will prompt to allow Local Network access. Granting this permission lets Gomoku discover and communicate with peers on the same Wi‑Fi network.</p><p>Manage it at: <strong>System Settings → Privacy &amp; Security → Local Network</strong></p><p>If you accidentally denied the permission, toggle it on in the settings and restart Gomoku.</p><h2 id="files-and-folders-read-write-game-records" tabindex="-1">Files and Folders (read/write game records) <a class="header-anchor" href="#files-and-folders-read-write-game-records" aria-label="Permalink to &quot;Files and Folders (read/write game records)&quot;">​</a></h2><p>Gomoku asks for Files &amp; Folders access when you open or save game records (SGF) or export logs. Grant access to the directories you want Gomoku to read.</p><p>Manage it at: <strong>System Settings → Privacy &amp; Security → Files and Folders</strong></p><h2 id="screen-recording-accessibility-optional" tabindex="-1">Screen Recording / Accessibility (optional) <a class="header-anchor" href="#screen-recording-accessibility-optional" aria-label="Permalink to &quot;Screen Recording / Accessibility (optional)&quot;">​</a></h2><p>Some auxiliary features (for example, overlay helpers or advanced capture tools) may request Screen Recording or Accessibility permissions. These are optional and only needed if you enable the related feature in the app.</p><p>Manage them at:</p><ul><li><strong>Screen Recording</strong>: System Settings → Privacy &amp; Security → Screen Recording</li><li><strong>Accessibility</strong>: System Settings → Privacy &amp; Security → Accessibility</li></ul><h3 id="resetting-a-permission-with-terminal" tabindex="-1">Resetting a permission with Terminal <a class="header-anchor" href="#resetting-a-permission-with-terminal" aria-label="Permalink to &quot;Resetting a permission with Terminal&quot;">​</a></h3><p>If a permission dialog was dismissed or the state is inconsistent, you can reset macOS permission prompts for an app using <code>tccutil</code>. Replace the bundle id if different:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reset ScreenCapture prompts for Gomoku</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ScreenCapture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.gomoku</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reset Local Network prompts (resets all local network prompts)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LocalNetwork</span></span></code></pre></div><p>After running <code>tccutil</code>, restart the app and trigger the feature again to reprompt.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>If LAN games are not discovered, ensure Local Network permission is allowed and that devices are on the same network (no AP/client isolation).</li><li>If saving/opening SGF files fails, check Files &amp; Folders permission and try saving to <code>Documents</code> first.</li><li>If the app still behaves unexpectedly after changing permissions, try quitting and reopening Gomoku.</li></ul><p>If you need help locating where logs or application data are stored, see <code>docs/macos-sandbox-paths.md</code> in the project documentation.</p>`,20)])])}const g=a(r,[["render",o]]);export{m as __pageData,g as default};
